im=np.array(Image.open('/app/target.png').convert('L')); m=im<80;l,n=ndi.label(m,structure=np.ones((3,3)))
# thinning target
A=m.astype(np.uint8);it=0;changed=True
while changed and it<200:
 changed=False;it+=1
 for phase in (0,1):
  p=np.pad(A,1); ns=[p[:-2,1:-1],p[:-2,2:],p[1:-1,2:],p[2:,2:],p[2:,1:-1],p[2:,:-2],p[1:-1,:-2],p[:-2,:-2]];B=sum(ns);tr=sum(((ns[k]==0)&(ns[(k+1)%8]==1)).astype(np.uint8) for k in range(8)); c=(A==1)&(B>=2)&(B<=6)&(tr==1)
  if phase==0:c &= (ns[0]*ns[2]*ns[4]==0)&(ns[2]*ns[4]*ns[6]==0)
  else:c &= (ns[0]*ns[2]*ns[6]==0)&(ns[0]*ns[4]*ns[6]==0)
  if c.any(): A[c]=0;changed=True
for i in range(1,n+1):
 c=l==i; area=int(c.sum()); sk=A.astype(bool)&c; # approximate skeleton geodesic length by count nodes minus components, diag edges weighted
 y,x=np.where(sk); sset=set(zip(y,x)); length=0
 for yy,xx in sset:
  for dy,dx,w in [(0,1,1),(1,-1,2**.5),(1,0,1),(1,1,2**.5)]:
   if (yy+dy,xx+dx) in sset:length+=w
 length/=2
 print(i,'area',area,'skpix',sk.sum(),'sklen',length,'meanwidthpx',area/length,'mm',area/length*.22186)
